151	    protected void editFirstRow(WebElement table) {
152	        WebElement edit = waitUntilElementIsClickable(table, By.cssSelector("tbody td:nth-last-child(2) button"));
153	        edit.click();
154	        waitUntilElementIsDetached(edit);
155	    }
156	
157	    protected int getNumberOfLines(WebElement table) {
158	        return table.findElements(By.xpath("tbody[1]/tr")).size();
159	    }
160	
161	    protected String getCellText(WebElement table, String columnName, int row) {
162	        int columnIndex = getColumnIndex(table, columnName);
163	
164	        WebElement element = table.findElement(By.xpath("tbody[1]/tr[" + row + "]/td[" + columnIndex + "]"));
165	        moveToElement(element);
166	
167	        return element.getText();
168	    }
169	
170	    protected int getColumnIndex(WebElement table, String columnName) {
171	        List<WebElement> tableHeaders = table.findElements(By.cssSelector("thead th"));
172	
173	        int index = 1;
174	        for (WebElement tableHeader : tableHeaders) {
175	            moveToElement(tableHeader);
176	            if (columnName.equals(tableHeader.getText())) {
177	                return index;
178	            }
179	            index++;
180	        }
181	
182	        return 0;
183	    }
184	
185	    private void moveToElement(WebElement tableHeader) {
186	        Actions action = new Actions(webDriver);
187	        action.moveToElement(tableHeader);
188	        action.build().perform();
189	    }
190	}
