225	public class BasePage {
226	    @Inject
227	    protected WebDriver webDriver;
228	
229	    public void getUrl(String url) {
230	        webDriver.get(url);
231	    }
232	
233	    public String getCurrentUrl() {
234	        return webDriver.getCurrentUrl();
235	    }
236	
237	    public void waitUntilPlaceIsLoaded(final String nameToken) {
238	        webDriverWait().until(new Function<WebDriver, Boolean>() {
239	            @Override
240	            public Boolean apply(WebDriver webDriver) {
241	                return webDriver.getCurrentUrl().contains("#" + nameToken);
242	            }
243	        });
244	    }
245	
246	    protected void chooseOkOnNextConfirm() {
247	        ((JavascriptExecutor) webDriver).executeScript("window.confirm = function(msg){return true;};");
248	    }
249	
250	    protected void chooseCancelOnNextConfirm() {
251	        ((JavascriptExecutor) webDriver).executeScript("window.confirm = function(msg){return false;};");
252	    }
253	
254	    protected WebElement waitUntilElementIsLoaded(String id) {
255	        return waitUntilElementIsLoaded(By.id(id));
256	    }
257	
258	    protected WebElement waitUntilElementIsLoaded(By locator) {
259	        return waitUntilElementIsLoaded(webDriver, locator);
260	    }
261	
262	    protected void waitUntilElementIsVisible(WebElement element) {
263	        webDriverWait().until(ExpectedConditions.visibilityOf(element));
264	    }
265	
266	    protected WebElement waitUntilElementIsVisible(By locator) {
267	        return webDriverWait().until(ExpectedConditions.visibilityOfElementLocated(locator));
268	    }
269	
270	    protected void waitUntilElementIsDetached(WebElement element) {
271	        webDriverWait().until(ExpectedConditions.stalenessOf(element));
272	    }
273	
274	    protected WebElement waitUntilElementIsClickable(final WebElement parent,
275	            final By locator) {
276	        final WebElement childElement = webDriverWait().until(new Function<WebDriver, WebElement>() {
277	            @Override
278	            public WebElement apply(WebDriver input) {
279	                return parent.findElement(locator);
280	            }
281	        });
282	
283	        moveToElement(childElement);
284	
285	        webDriverWait().until(new Function<WebDriver, Boolean>() {
286	            @Override
287	            public Boolean apply(WebDriver input) {
288	                return childElement.isEnabled();
289	            }
290	        });
291	
292	        return childElement;
293	    }
294	
295	    protected WebElement waitUntilElementIsClickable(By locator) {
296	        moveToElementLocatedBy(locator);
297	
298	        return webDriverWait().until(ExpectedConditions.elementToBeClickable(locator));
299	    }
300	
301	    protected WebElement waitUntilPresenceOfElementLocated(By locator) {
302	        return webDriverWait().until(ExpectedConditions.presenceOfElementLocated(locator));
303	    }
304	
305	    protected WebElement waitUntilElementIsLoaded(final SearchContext parent, final By locator) {
306	        return webDriverWait().until(new ExpectedCondition<WebElement>() {
307	            @Override
308	            public WebElement apply(WebDriver input) {
309	                return parent.findElement(locator);
310	            }
311	        });
312	    }
313	
314	    private void moveToElementLocatedBy(By by) {
315	        WebElement webElement = waitUntilPresenceOfElementLocated(by);
316	        moveToElement(webElement);
317	    }
318	
319	    private void moveToElement(WebElement webElement) {
320	        Actions actions = new Actions(webDriver);
321	        actions.moveToElement(webElement);
322	        actions.perform();
323	    }
324	
325	    private WebDriverWait webDriverWait() {
326	        return new WebDriverWait(webDriver, TestParameters.TIME_OUT_IN_SECONDS);
327	    }
328	}
