967	    private static final String RATING_COL = "Rating";
968	
969	    private HashMap<String, AveragingCounter> averages = new HashMap<String, AveragingCounter>();
970	
971	    public void addRating(String car, String rating) {
972	        String manufacturer = car.substring(0, car.indexOf('/'));
973	
974	        if (averages.containsKey(manufacturer)) {
975	            averages.get(manufacturer).add(Double.valueOf(rating));
976	        } else {
977	            averages.put(manufacturer, new AveragingCounter(Double.valueOf(rating)));
978	        }
979	    }
980	
981	    public boolean checkManufacturerAverages() {
982	        boolean match = true;
983	
984	        for (int row = 1; row <= getNumberOfLines(getReportsTable()); row++) {
985	            String manufacturer = getCellText(getReportsTable(), MANUFACTURER_COL, row);
986	            Double average = Double.valueOf(getCellText(getReportsTable(), RATING_COL, row));
987	            Double referenceAverage = averages.get(manufacturer).average();
988	
989	            if (!almostEqual(average, referenceAverage, 0.001d)) {
990	                match &= false;
991	            }
992	        }
993	
994	        return match;
995	    }
