1000	
1001	    private boolean almostEqual(Double a, Double b, double epsilon) {
1002	        return Math.abs(a - b) < epsilon;
1003	    }
1004	
1005	    private class AveragingCounter {
1006	        private double sum;
1007	        private int count;
1008	
1009	        AveragingCounter(double number) {
1010	            this.sum = number;
1011	            this.count = 1;
1012	        }
1013	
1014	        void add(double number) {
1015	            this.sum += number;
1016	            this.count++;
1017	        }
1018	
1019	        double average() {
1020	            return count == 0 ? Double.NaN : sum / count;
