import { Injectable, signal } from '@angular/core';

export type MessageStyle = 'SUCCESS' | 'ERROR';

/** MessageCloseDelay: NEVER = 0, DEFAULT = 5000 ms. */
export const MessageCloseDelay = { NEVER: 0, DEFAULT: 5000 } as const;

export interface Message {
  id: number;
  text: string;
  style: MessageStyle;
  closing: boolean;
}

const FADE_MS = 300;

/** Replaces DisplayMessageEvent + MessagesPresenter. */
@Injectable({ providedIn: 'root' })
export class MessageService {
  private nextId = 1;
  readonly messages = signal<Message[]>([]);

  success(text: string): void {
    this.display(text, 'SUCCESS');
  }

  error(text: string): void {
    this.display(text, 'ERROR');
  }

  display(text: string, style: MessageStyle, closeDelay: number = MessageCloseDelay.DEFAULT): void {
    const message: Message = { id: this.nextId++, text, style, closing: false };
    this.messages.update((list) => [...list, message]);
    if (closeDelay !== MessageCloseDelay.NEVER) {
      setTimeout(() => this.close(message.id), closeDelay);
    }
  }

  close(id: number): void {
    const target = this.messages().find((m) => m.id === id);
    if (!target || target.closing) {
      return;
    }
    this.messages.update((list) => list.map((m) => (m.id === id ? { ...m, closing: true } : m)));
    setTimeout(() => this.messages.update((list) => list.filter((m) => m.id !== id)), FADE_MS);
  }
}

/** Extracts a readable error text from a failed REST call. */
export function errorText(prefix: string, err: unknown): string {
  const e = err as { status?: number; statusText?: string; error?: unknown };
  let detail = '';
  if (e && typeof e.error === 'string' && e.error.length < 200) {
    detail = e.error;
  } else if (e && e.status !== undefined) {
    detail = e.status === 0 ? 'server unreachable' : `${e.status} ${e.statusText ?? ''}`.trim();
  }
  return detail ? `${prefix}: ${detail}` : prefix;
}
