import { Component, OnInit, inject, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { ApiService, LIMIT_ALL } from '../shared/api.service';
import { CarDto, RatingDto } from '../shared/dto';
import { PopupComponent } from '../shared/popup.component';
import { MessageService, errorText } from '../widget/message/message.service';

/** EditRatingPresenter/View: popup to create a rating (pick a car, enter a rating). */
@Component({
  selector: 'app-edit-rating',
  standalone: true,
  imports: [FormsModule, PopupComponent],
  template: `
    @if (cars(); as allowedCars) {
      <app-popup (autoHide)="onCancel()">
        <div class="row">
          <label for="edit-rating-car">Car:</label>
          <select id="edit-rating-car" [ngModel]="car()" (ngModelChange)="car.set($event)">
            @for (c of allowedCars; track c) {
              <option [ngValue]="c">{{ renderCar(c) }}</option>
            }
          </select>
        </div>
        <div class="row">
          <label for="gwt-debug-ratingInput">Your rating:</label>
          <input
            type="text"
            inputmode="numeric"
            maxlength="3"
            id="gwt-debug-ratingInput"
            [ngModel]="rating()"
            (ngModelChange)="rating.set($event)"
            (keydown.enter)="onSave()"
          />
        </div>
        <div class="row buttons">
          <button type="button" id="gwt-debug-ratingSave" [disabled]="saving()" (click)="onSave()">Save</button>
          <button type="button" (click)="onCancel()">Close</button>
        </div>
      </app-popup>
    }
  `,
  styles: `
    .row { margin: 5px 0; }
    label { margin-right: 5px; }
    .buttons button { margin-right: 5px; }
  `,
})
export class EditRatingComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  readonly saved = output<RatingDto>();
  readonly closed = output<void>();

  /** Allowed cars; the popup is revealed once they are loaded. */
  protected readonly cars = signal<CarDto[] | null>(null);
  protected readonly car = signal<CarDto | null>(null);
  protected readonly rating = signal('');
  protected readonly saving = signal(false);

  ngOnInit(): void {
    this.api.getCars(0, LIMIT_ALL).subscribe({
      next: (cars) => {
        const list = cars ?? [];
        this.car.set(list.length ? list[0] : null);
        this.cars.set(list);
      },
      error: (err) => {
        this.messages.error(errorText('Error loading the cars', err));
        this.closed.emit();
      },
    });
  }

  /** CarRenderer. */
  protected renderCar(car: CarDto): string {
    return car.manufacturer ? car.manufacturer.name + '/' + car.model : car.model;
  }

  protected onSave(): void {
    if (this.saving()) {
      return;
    }
    const text = String(this.rating() ?? '').trim();
    // IntegerBox: anything that does not parse as an integer has no value.
    const value = /^[-+]?\d+$/.test(text) ? parseInt(text, 10) : null;
    if (value === null) {
      this.messages.error('Please enter a valid rating');
      return;
    }
    if (!this.car()) {
      this.messages.error('Please choose a car');
      return;
    }
    const dto: RatingDto = { rating: value, car: this.car() };
    this.saving.set(true);
    this.api.saveOrCreateRating(dto).subscribe({
      next: (savedRating) => {
        this.saving.set(false);
        this.messages.success('Rating saved');
        this.saved.emit(savedRating);
      },
      error: (err) => {
        this.saving.set(false);
        this.messages.error(errorText('Error saving the rating', err));
      },
    });
  }

  protected onCancel(): void {
    this.closed.emit();
  }
}
