import { Component, OnInit, inject, signal } from '@angular/core';

import { ApiService } from '../shared/api.service';
import { RatingDto, formatNumber, ratingToString } from '../shared/dto';
import { MessageService, errorText } from '../widget/message/message.service';
import { EditRatingComponent } from './edit-rating.component';

/** RatingPresenter/View: the rating table with Delete per row. */
@Component({
  selector: 'app-rating',
  standalone: true,
  imports: [EditRatingComponent],
  template: `
    <div class="bigTitle">
      <h2><span>Ratings</span></h2>
      <div>
        <button type="button" class="addAction" id="gwt-debug-ratingCreate" (click)="onCreate()">Create</button>
      </div>
      <span class="clear"></span>
    </div>
    <div class="tableWrapper">
      <table class="cellTable" id="gwt-debug-ratings" width="100%">
        <colgroup>
          <col />
          <col />
          <col />
          <col style="width: 75px" />
        </colgroup>
        <thead>
          <tr>
            <th>ID</th>
            <th>Car</th>
            <th>Rating</th>
            <th>Delete</th>
          </tr>
        </thead>
        <tbody>
          @for (rating of ratings(); track rating) {
            <tr>
              <td>{{ formatNumber(rating.id) }}</td>
              <td>{{ ratingToString(rating) }}</td>
              <td>{{ formatNumber(rating.rating) }}</td>
              <td><button type="button" (click)="onDeleteClicked(rating)">Delete</button></td>
            </tr>
          }
        </tbody>
      </table>
    </div>
    @if (editing()) {
      <app-edit-rating (saved)="onRatingAdded($event)" (closed)="editing.set(false)" />
    }
  `,
  styleUrl: '../shared/page.css',
})
export class RatingComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  protected readonly formatNumber = formatNumber;
  protected readonly ratingToString = ratingToString;
  protected readonly ratings = signal<RatingDto[]>([]);
  protected readonly editing = signal(false);

  ngOnInit(): void {
    this.api.getRatings().subscribe({
      next: (ratings) => this.ratings.set(ratings ?? []),
      error: (err) => this.messages.error(errorText('Error loading the ratings', err)),
    });
  }

  protected onCreate(): void {
    this.editing.set(true);
  }

  protected onDeleteClicked(rating: RatingDto): void {
    if (window.confirm('Are you sure you want to delete ' + ratingToString(rating) + '?')) {
      this.api.deleteRating(rating.id as number).subscribe({
        next: () => this.ratings.update((list) => list.filter((r) => r !== rating && r.id !== rating.id)),
        error: (err) => this.messages.error(errorText('Error deleting the rating', err)),
      });
    }
  }

  protected onRatingAdded(rating: RatingDto): void {
    this.ratings.update((list) => [...list, rating]);
    this.editing.set(false);
  }
}
