import { routes } from './app.routes';
import { HashTokenLocationStrategy } from './shared/hash-token-location-strategy';

export const appConfig: ApplicationConfig = {
  providers: [
    provideZoneChangeDetection({ eventCoalescing: true }),
    provideRouter(routes),
    // Hash-based routing with GWT history tokens ("#manufacturer").
    { provide: LocationStrategy, useClass: HashTokenLocationStrategy },
    provideHttpClient(),
  ],
};
