async function ev(expr) { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails).slice(0, 400)); return r.result.value; }
async function waitFor(expr, what, timeout = 10000) { const t = Date.now(); while (Date.now() - t < timeout) { try { const v = await ev(expr); if (v) return v; } catch (e) {} await sleep(100); } throw new Error('Timeout waiting for ' + what); }
const byId = (dbg) => `document.getElementById('gwt-debug-${dbg}')`;
const visible = (el) => `(function(e){if(!e)return false;const r=e.getBoundingClientRect();const s=getComputedStyle(e);return r.width>0&&r.height>0&&s.visibility!=='hidden'&&parseFloat(s.opacity)>0.1;})(${el})`;
async function clickExpr(el, what) {
  await waitFor(visible(el), what + ' visible');
  const p = await ev(`(function(){const e=${el};e.scrollIntoView({block:'center'});const r=e.getBoundingClientRect();const x=r.left+r.width/2,y=r.top+r.height/2;const top=document.elementFromPoint(x,y);return {x,y,ok:e===top||e.contains(top),top:top&&top.outerHTML.slice(0,80)};})()`);
  if (!p.ok) throw new Error('click intercepted on ' + what + ' by ' + p.top);
  for (const type of ['mousePressed', 'mouseReleased']) await send('Input.dispatchMouseEvent', { type, x: p.x, y: p.y, button: 'left', clickCount: 1 });
}
async function mark(el, name) { await ev(`window['${name}']=${el}, true`); }
async function waitStale(name) { await waitFor(`!document.contains(window['${name}'])`, name + ' stale'); }
const rows = (dbg) => ev(`${byId(dbg)}.querySelectorAll(':scope > tbody:first-of-type > tr').length`);
async function cellText(dbg, col, row) { return ev(`(function(){const t=${byId(dbg)};const hs=[...t.querySelectorAll('thead th')].map(h=>h.innerText);const ci=hs.indexOf('${col}');const r=t.querySelector('tbody').rows[${row}-1];return r.cells[ci].innerText;})()`); }
async function navigate(token) {
  await waitFor(visible(byId('menubar')), 'menubar');
  // HeaderWidgetPage: //a[contains(@href, token)] (document-wide, first match)
  const el = `document.evaluate("//a[contains(@href,'${token}')]",document,null,9,null).singleNodeValue`;
  await clickExpr(el, 'link ' + token);
  await waitFor(`location.href.includes('#${token}')`, 'place ' + token);
}
async function okConfirm() { await ev(`window.confirm=function(){return true;}, true`); }
async function hasSuccess(msg = '') {
  // MessageWidgetPage.messageContains + visibility
  for (let i = 0; i < 10; i++) {
    await waitFor(byId('successMessage'), 'success message');
    const txt = await ev(`${byId('successMessage')}.querySelector('span').innerText`);
    if (txt && txt.includes(msg)) { await waitFor(visible(byId('successMessage')), 'success visible'); return true; }
    await mark(byId('successMessage'), '__msg');
    await clickExpr(`${byId('successMessage')}.querySelector('span:last-child')`, 'close msg');
    await waitStale('__msg');
  }
  return false;
}
function assert(c, m) { if (!c) throw new Error('Assertion failed: ' + m); }

async function freshPage() { await send('Page.navigate', { url: 'about:blank' }); await sleep(200); await send('Page.navigate', { url: BASE }); await waitFor(`document.readyState==='complete' && !!${byId('menubar')}`, 'app loaded'); }

const scenarios = {
  'M: create shows editor': async () => {
    await navigate('manufacturer'); const n = await rows('manufacturers');
    await clickExpr(byId('create-manufacturer'), 'create'); await sleep(1500);
    assert(await waitFor(visible(byId('manufacturer-editor')), 'editor'), 'editor visible');
  },
  'M: close leaves table': async () => {
    await navigate('manufacturer'); await waitFor(`${byId('manufacturers')}.querySelector('tbody tr')`, 'rows');
    const n = await rows('manufacturers');
    await clickExpr(byId('create-manufacturer'), 'create'); await sleep(1500);
    await waitFor(visible(byId('manufacturer-editor')), 'editor');
    await clickExpr(byId('manufacturer-input'), 'input'); await send('Input.insertText', { text: 'Ford' });
    await clickExpr(byId('manufacturer-close'), 'close');
    assert((await rows('manufacturers')) === n, 'rows unchanged');
  },
  'M: save adds row': async () => {
    await navigate('manufacturer'); await waitFor(`${byId('manufacturers')}.querySelector('tbody tr')`, 'rows');
    const n = await rows('manufacturers');
    await clickExpr(byId('create-manufacturer'), 'create'); await sleep(1500);
    await waitFor(visible(byId('manufacturer-editor')), 'editor');
    await ev(`${byId('manufacturer-input')}.value=''`);
    await clickExpr(byId('manufacturer-input'), 'input'); await send('Input.insertText', { text: 'Plymouth' });
    await clickExpr(byId('manufacturer-save'), 'save');
    assert(await hasSuccess('saved'), 'success saved');
    assert((await rows('manufacturers')) > n, 'rows incremented');
    const last = await cellText('manufacturers', 'Name', await rows('manufacturers'));
    assert(last === 'Plymouth', 'last is Plymouth, got ' + last);
  },
  'M: edit first': async () => {
    await navigate('manufacturer');
    await waitFor(`${byId('manufacturers')}.querySelector('tbody td:nth-last-child(2) button')`, 'edit btn');
    await clickExpr(`${byId('manufacturers')}.querySelector('tbody td:nth-last-child(2) button')`, 'edit'); await sleep(1500);
    await ev(`${byId('manufacturer-input')}.value=''`);
    await ev(`${byId('manufacturer-input')}.dispatchEvent(new Event('input'))`);
    await clickExpr(byId('manufacturer-input'), 'input'); await send('Input.insertText', { text: 'Ford' });
    await clickExpr(byId('manufacturer-save'), 'save');
    assert(await hasSuccess('saved'), 'success');
    const first = await cellText('manufacturers', 'Name', 1);
    assert(first === 'Ford', 'first is Ford, got ' + first);
  },
  'M: delete first': async () => {
    await navigate('manufacturer');
    await waitFor(`${byId('manufacturers')}.querySelector('tbody td:last-child button')`, 'del btn');
    const n = await rows('manufacturers');
    await mark(`${byId('manufacturers')}.querySelector('tbody td:last-child button')`, '__del');
    await okConfirm();
    await clickExpr(`window.__del`, 'delete'); await waitStale('__del');
    assert((await rows('manufacturers')) === n - 1, 'row removed');
  },
  'R: add rating': async () => {
    await navigate('rating'); await waitFor(`${byId('ratings')}.querySelector('tbody tr')`, 'rows');
    const n = await rows('ratings');
    await clickExpr(byId('ratingCreate'), 'create');
    await waitFor(visible(byId('ratingInput')), 'rating input');
    await clickExpr(byId('ratingInput'), 'input'); await send('Input.insertText', { text: '10' });
    await mark(byId('ratingSave'), '__save'); await clickExpr('window.__save', 'save'); await waitStale('__save');
    assert(await hasSuccess(), 'success');
    assert((await rows('ratings')) === n + 1, 'rating added');
  },
  'R: delete rating': async () => {
    await navigate('rating');
    await waitFor(`${byId('ratings')}.querySelector('tbody td:last-child button')`, 'del');
    const n = await rows('ratings');
    await mark(`${byId('ratings')}.querySelector('tbody td:last-child button')`, '__del');
    await okConfirm(); await clickExpr('window.__del', 'delete'); await waitStale('__del');
    assert((await rows('ratings')) === n - 1, 'rating removed');
  },
  'Rep: averages': async () => {
    await navigate('rating'); await waitFor(`${byId('ratings')}.querySelector('tbody tr')`, 'rows');
    const n = await rows('ratings'); const avg = {};
    for (let i = 1; i <= n; i++) { const car = await cellText('ratings', 'Car', i); const r = parseFloat(await cellText('ratings', 'Rating', i)); const m = car.substring(0, car.indexOf('/')); (avg[m] ||= []).push(r); }
    await navigate('report'); await waitFor(`${byId('reports')}.querySelector('tbody tr')`, 'report rows');
    const rn = await rows('reports');
    for (let i = 1; i <= rn; i++) { const m = await cellText('reports', 'Manufacturer', i); const a = parseFloat(await cellText('reports', 'Rating', i)); const ref = avg[m].reduce((x, y) => x + y) / avg[m].length; assert(Math.abs(a - ref) < 0.001, `avg ${m} ${a} vs ${ref}`); }
    console.log('   report rows', rn, JSON.stringify(avg));
  },
};

